void take(const std::string&) { std::cout << "copy\n"; }
void take(std::string&&)      { std::cout << "move\n"; }

template <class T>
void wrapper(T&& arg) {
    take(arg);                  // arg has a name: lvalue
}

std::string s = "hi";
wrapper(s);                     // fine: copy
wrapper(std::string("hi"));     // a temporary... still copies

template <class T>
void wrapper(T&& arg) {
    take(std::forward<T>(arg));
}

std::string s = "hi";
wrapper(s);                     // copy
wrapper(std::string("hi"));     // move

template <class T, class... Args>
std::unique_ptr<T> my_make_unique(Args&&... args) {
    return std::unique_ptr<T>(new T(std::forward<Args>(args)...));
}

